#include <iostream>
using namespace std;

int square(int x) {
    return x * x;   //@ @guide {x} @tts [step-out] 這裡把 x 乘上 x，然後跳回呼叫它的地方
}

int main() {   //@ @layout open:visualizer
    int a = 4;   //@ @tts [next] 先準備 a，值是四
    int b = square(a);   //@ @tts [step-in] 呼叫 square，進到函式裡面看看 | @2 [next] 回到呼叫的地方，結果存進 b
    cout << b << endl;   //@ @guide {b} @tts [next] b 現在是 {b}
    return 0;   //@ @tts [continue] 程式結束
}
